/**
 * Explicit TypeScript interfaces for staff members (users).
 * Mirrors the DB schema's `users` table but is decoupled from Drizzle inference.
 */

export interface StaffMember {
  id: string
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive: boolean
  createdAt: Date
}

/** Input for creating a new staff member. */
export interface NewStaffMember {
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive?: boolean
}

/** Input for updating an existing staff member (partial). */
export interface UpdateStaffMember {
  name?: string
  role?: 'mechanic' | 'manager'
  hourlyRate?: number // cents per hour
  isActive?: boolean
}

/** Aggregated performance statistics for a single staff member. */
export interface StaffStats {
  /** Total minutes worked from completed work log timers (endedAt IS NOT NULL) */
  totalHoursWorked: number
  /** Count of repairs assigned to this user with status = 'completed' */
  completedRepairs: number
  /** Count of repairs assigned to this user where status is NOT 'completed' or 'cancelled' */
  activeRepairs: number
  /** Average repair duration in minutes (totalHoursWorked / completedRepairs), null if no completions */
  avgRepairDurationMinutes: number | null
}

import { z } from 'zod'

// ---------------------------------------------------------------------------
// Role enum
// ---------------------------------------------------------------------------

export const staffRoleSchema = z.enum(['mechanic', 'manager'])

/** A staff member role */
export type StaffRole = z.infer<typeof staffRoleSchema>

// ---------------------------------------------------------------------------
// Create input schema
// ---------------------------------------------------------------------------

/** Input for creating a new staff member. */
export const createStaffMemberSchema = z.object({
  id: z.string().uuid('id must be a valid UUID').optional(),
  name: z.string().min(1, 'name is required').max(200),
  role: staffRoleSchema.default('mechanic'),
  hourlyRate: z.number()
    .int('hourlyRate must be an integer (cents)')
    .positive('hourlyRate must be positive'),
  isActive: z.boolean().optional(),
})

/** Input for creating a new staff member. */
export type CreateStaffMemberInput = z.infer<typeof createStaffMemberSchema>

// ---------------------------------------------------------------------------
// Update input schema — partial fields, at least one required
// ---------------------------------------------------------------------------

const updatableFields = [
  'name', 'role', 'hourlyRate', 'isActive'
] as const

/** Input for updating an existing staff member (partial). */
export const updateStaffMemberSchema = z.object({
  name: z.string().min(1, 'name must not be empty').max(200).optional(),
  role: staffRoleSchema.optional(),
  hourlyRate: z.number()
    .int('hourlyRate must be an integer (cents)')
    .positive('hourlyRate must be positive')
    .optional(),
  isActive: z.boolean().optional(),
}).refine(
  data => updatableFields.some(key => data[key] !== undefined),
  { message: 'At least one field must be provided for update' }
)

/** Input for updating an existing staff member. */
export type UpdateStaffMemberInput = z.infer<typeof updateStaffMemberSchema>

/**
 * Users Service — Worker lookup for repair assignment and staff management.
 */

import crypto from 'crypto'
import { asc, eq, sql } from 'drizzle-orm'
import { db } from '../db/index.js'
import { users, workLogs, repairs, type User as DbUser } from '../db/schema.js'
import {
  createStaffMemberSchema,
  updateStaffMemberSchema,
  type CreateStaffMemberInput,
  type UpdateStaffMemberInput,
} from '@shared/validations/staff.js'

// ---------------------------------------------------------------------------
// Types — compact dropdown shape (existing)
// ---------------------------------------------------------------------------

/** Compact worker shape for dropdown selectors (name + role only) */
export interface WorkerOption {
  id: string
  name: string
  role: 'mechanic' | 'manager'
}

// ---------------------------------------------------------------------------
// Types — paginated management list
// ---------------------------------------------------------------------------

/** Full staff member detail for the management list. */
export interface StaffMemberDetail {
  id: string
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive: boolean
  createdAt: Date
}

/** Query parameters for the paginated staff list. */
export interface StaffListQuery {
  /** Search term — filters by name */
  search?: string
  /** Page number (1-indexed) */
  page?: number
  /** Items per page */
  pageSize?: number
}

/** Paginated response for the staff management list. */
export interface StaffPaginatedResponse {
  users: StaffMemberDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Functions — compact dropdown (existing)
// ---------------------------------------------------------------------------

/**
 * List all active workers, suitable for populating a worker assignment dropdown.
 * Returns workers sorted by name for consistent display order.
 */
export async function getActiveWorkers(): Promise<WorkerOption[]> {
  const rows = await db
    .select({
      id: users.id,
      name: users.name,
      role: users.role,
    })
    .from(users)
    .where(eq(users.isActive, true))
    .orderBy(users.name)

  return rows as unknown as WorkerOption[]
}

// ---------------------------------------------------------------------------
// Functions — create staff member
// ---------------------------------------------------------------------------

/**
 * Create a new staff member.
 *
 * Generates a UUID if not provided, applies defaults (role=mechanic, isActive=true),
 * and inserts into the users table. Returns the created StaffMemberDetail.
 */
export async function createUser(input: CreateStaffMemberInput): Promise<StaffMemberDetail> {
  const validated = createStaffMemberSchema.parse(input)

  const dbData = {
    id: validated.id ?? crypto.randomUUID(),
    name: validated.name,
    role: validated.role as 'mechanic' | 'manager',
    hourlyRate: validated.hourlyRate,
    isActive: validated.isActive ?? true,
  }

  const [created] = await db.insert(users).values(dbData).returning()
  return toStaffMemberDetail(created)
}

// ---------------------------------------------------------------------------
// Functions — paginated management list
// ---------------------------------------------------------------------------

/**
 * Get paginated staff member list with optional search filtering.
 *
 * Returns full StaffMemberDetail records suitable for the management view.
 * Search filters by name using SQL LIKE. Includes both active and inactive members.
 *
 * @param query - Optional search term, page number, and page size
 * @returns Paginated response with staff members and pagination metadata
 */
export async function listUsersPaginated(
  query: StaffListQuery = {}
): Promise<StaffPaginatedResponse> {
  const { search, page = 1, pageSize = 25 } = query
  const offset = (page - 1) * pageSize

  // Build filter conditions for search
  let whereClause: ReturnType<typeof sql> | undefined

  if (search && search.trim()) {
    const term = `%${search.trim()}%`
    whereClause = sql`LOWER(${users.name}) LIKE ${term.toLowerCase()}`
  }

  // Get total count for pagination
  let totalCount = 0
  if (whereClause) {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(users).where(whereClause)
    totalCount = count
  } else {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(users)
    totalCount = count
  }

  // Get paginated results
  let results: DbUser[]
  if (whereClause) {
    results = await db.select().from(users).where(whereClause)
      .orderBy(asc(users.name))
      .limit(pageSize)
      .offset(offset)
  } else {
    results = await db.select().from(users)
      .orderBy(asc(users.name))
      .limit(pageSize)
      .offset(offset)
  }

  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize))

  return {
    users: results.map(toStaffMemberDetail),
    totalItems: totalCount,
    currentPage: page,
    pageSize,
    totalPages,
  }
}

// ---------------------------------------------------------------------------
// Custom Error Classes
// ---------------------------------------------------------------------------

export class StaffNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Staff member not found: ${id}`)
    this.name = 'StaffNotFoundError'
  }
}

// ---------------------------------------------------------------------------
// Functions — get by ID
// ---------------------------------------------------------------------------

/**
 * Get a single staff member by ID.
 *
 * @throws StaffNotFoundError if user doesn't exist
 */
export async function getUserById(id: string): Promise<StaffMemberDetail> {
  const [user] = await db.select().from(users).where(eq(users.id, id))

  if (!user) {
    throw new StaffNotFoundError(id)
  }

  return toStaffMemberDetail(user)
}

// ---------------------------------------------------------------------------
// Functions — update staff member (partial)
// ---------------------------------------------------------------------------

/**
 * Update an existing staff member with partial fields.
 *
 * Only provided fields are changed. Validates against Zod schema which requires
 * at least one field to be present.
 *
 * @throws StaffNotFoundError if user doesn't exist
 * @throws ZodError if validation fails (empty payload, invalid role, etc.)
 */
export async function updateUser(
  id: string,
  input: UpdateStaffMemberInput,
): Promise<StaffMemberDetail> {
  // Validate — ensures at least one field is provided and values are valid
  const validated = updateStaffMemberSchema.parse(input)

  // Build partial DB update object (only include defined fields)
  const dbUpdate: Record<string, unknown> = {}
  if (validated.name !== undefined) dbUpdate.name = validated.name
  if (validated.role !== undefined) dbUpdate.role = validated.role as 'mechanic' | 'manager'
  if (validated.hourlyRate !== undefined) dbUpdate.hourlyRate = validated.hourlyRate
  if (validated.isActive !== undefined) dbUpdate.isActive = validated.isActive

  const [updated] = await db
    .update(users)
    .set(dbUpdate)
    .where(eq(users.id, id))
    .returning()

  if (!updated) {
    throw new StaffNotFoundError(id)
  }

  return toStaffMemberDetail(updated)
}

// ---------------------------------------------------------------------------
// Helpers — map between DB User and DTO shapes
// ---------------------------------------------------------------------------

/** Map a DB User to the full staff member detail shape. */
function toStaffMemberDetail(user: DbUser): StaffMemberDetail {
  return {
    id: user.id,
    name: user.name,
    role: user.role as 'mechanic' | 'manager',
    hourlyRate: user.hourlyRate,
    isActive: user.isActive,
    createdAt: user.createdAt,
  }
}

// ---------------------------------------------------------------------------
// Types — staff stats aggregation
// ---------------------------------------------------------------------------

/** Aggregated performance statistics for a single staff member. */
export interface StaffStats {
  /** Total minutes worked from completed work log timers (endedAt IS NOT NULL) */
  totalHoursWorked: number
  /** Count of repairs assigned to this user with status = 'completed' */
  completedRepairs: number
  /** Count of repairs assigned to this user where status is NOT 'completed' or 'cancelled' */
  activeRepairs: number
  /** Average repair duration in minutes (totalHoursWorked / completedRepairs), null if no completions */
  avgRepairDurationMinutes: number | null
}

// ---------------------------------------------------------------------------
// Functions — staff stats aggregation (pure computation, no side effects)
// ---------------------------------------------------------------------------

/**
 * Aggregate staff performance statistics from workLogs and repairs.
 *
 * Pure computation function — reads data but produces no side effects.
 * - totalHoursWorked: SUM of (endedAt - startedAt) in minutes from completed work logs
 * - completedRepairs: COUNT of assigned repairs with status = 'completed'
 * - activeRepairs: COUNT of assigned repairs NOT in ('completed', 'cancelled')
 * - avgRepairDurationMinutes: totalHoursWorked / completedRepairs (null if 0 completions)
 */
export async function computeStaffStats(userId: string): Promise<StaffStats> {
  // Total minutes worked from completed work log timers
  const [{ totalMs }] = await db
    .select({ totalMs: sql<number>`COALESCE(SUM(${workLogs.endedAt} - ${workLogs.startedAt}), 0)` })
    .from(workLogs)
    .where(
      sql`${workLogs.userId} = ${userId} AND ${workLogs.endedAt} IS NOT NULL`
    )

  const totalHoursWorked = Math.round(totalMs / 60_000) // ms → minutes, rounded

  // Completed repairs count
  const [{ completedCount }] = await db
    .select({ completedCount: sql<number>`count(*)` })
    .from(repairs)
    .where(
      sql`${repairs.assignedTo} = ${userId} AND ${repairs.status} = 'completed'`
    )

  // Active repairs count (not completed, not cancelled)
  const [{ activeCount }] = await db
    .select({ activeCount: sql<number>`count(*)` })
    .from(repairs)
    .where(
      sql`${repairs.assignedTo} = ${userId} AND ${repairs.status} NOT IN ('completed', 'cancelled')`
    )

  const completedRepairs = completedCount
  const activeRepairs = activeCount
  const avgRepairDurationMinutes = completedRepairs > 0 ? totalHoursWorked / completedRepairs : null

  return { totalHoursWorked, completedRepairs, activeRepairs, avgRepairDurationMinutes }
}

/**
 * Users Routes — Worker lookup for repair assignment and staff management.
 */

import { Hono } from 'hono'
import {
  getActiveWorkers,
  listUsersPaginated,
  createUser,
  getUserById,
  updateUser,
  computeStaffStats,
  StaffNotFoundError,
  type StaffListQuery,
} from '../services/users.service.js'
import { createStaffMemberSchema, updateStaffMemberSchema } from '@shared/validations/staff.js'

const usersRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /users — Dual-mode endpoint
//
// When called without query parameters, returns a compact shape:
// id, name, role. Only active workers (isActive=true).
// Suitable for populating repair assignment dropdowns.
//
// When called with ?search= and/or ?page= parameters, returns full staff member
// details with pagination — suitable for the management list view.
// ---------------------------------------------------------------------------

usersRoutes.get('/', async (c) => {
  const search = c.req.query('search')
  const page = c.req.query('page')
  const pageSize = c.req.query('pageSize')

  // If pagination or search params are present, return paginated full details
  if (search !== undefined || page !== undefined || pageSize !== undefined) {
    const query: StaffListQuery = {}
    if (search !== undefined && search !== '') query.search = search
    if (page !== undefined) query.page = parseInt(page, 10)
    if (pageSize !== undefined) query.pageSize = parseInt(pageSize, 10)

    return c.json(await listUsersPaginated(query))
  }

  // Default: compact selector shape for POS dropdown consumers
  const workers = await getActiveWorkers()
  return new Response(JSON.stringify(workers), {
    headers: { 'Content-Type': 'application/json' },
  })
})

// ---------------------------------------------------------------------------
// POST /users — Create a new staff member
// ---------------------------------------------------------------------------

usersRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    const validated = createStaffMemberSchema.parse(input)
    const user = await createUser(validated)
    return c.json(user, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }
    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

// ---------------------------------------------------------------------------
// PATCH /users/:id — Update a staff member (partial update)
// ---------------------------------------------------------------------------

usersRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    const input = await c.req.json()
    const validated = updateStaffMemberSchema.parse(input)
    const user = await updateUser(id, validated)
    return c.json(user)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    if (err instanceof StaffNotFoundError) {
      return c.json({ error: 'Staff member not found', code: 'NOT_FOUND' }, 404)
    }

    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

// ---------------------------------------------------------------------------
// GET /users/:id/stats — Staff performance statistics
// ---------------------------------------------------------------------------

usersRoutes.get('/:id/stats', async (c) => {
  const id = c.req.param('id')

  // Verify user exists before computing stats
  try {
    await getUserById(id)
  } catch (err) {
    if (err instanceof StaffNotFoundError) {
      return c.json({ error: 'Staff member not found', code: 'NOT_FOUND' }, 404)
    }
    throw err
  }

  const stats = await computeStaffStats(id)
  return c.json(stats)
})

export default usersRoutes

import { describe, it, expect, beforeEach } from 'vitest'
import crypto from 'crypto'
import type Database from 'better-sqlite3'
import { db, sqliteDb } from '@/db/index.js'
import { workLogs, users } from '@/db/schema.js'

// Raw SQL executor — avoids Drizzle Date/number conversion issues with timestamps
function run(sqlStr: string, params?: unknown[]): void {
  const client = sqliteDb as Database.Database
  client.prepare(sqlStr).run(...(params ?? []))
}

// ---------------------------------------------------------------------------
// Helpers — create test fixtures in the DB
// ---------------------------------------------------------------------------

async function seedUser(): Promise<string> {
  const id = crypto.randomUUID()
  await db.insert(users).values({
    id,
    name: 'Test Technician',
    role: 'mechanic',
    hourlyRate: 5000, // 50 EUR/hour in cents
  })
  return id
}

/** Insert a repair with raw SQL (avoids Drizzle type issues) */
function insertRepair(repairId: string, bicycleId: string, assignedTo: string | null, status: string): void {
  const now = Date.now()
  run(
    'INSERT INTO repairs (id, bicycle_id, assigned_to, status, customer_notes, internal_notes, hold_reason, hold_reason_note, planned_date, pickup_date, completed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [repairId, bicycleId, assignedTo, status, null, null, null, null, null, null, null, now]
  )
}

async function seedRepair(assignedTo: string | null, status = 'in_progress'): Promise<string> {
  const id = crypto.randomUUID()
  insertRepair(id, 'bicycle-placeholder-id', assignedTo, status)
  return id
}

/** Insert a work log with raw SQL */
function insertWorkLog(workLogId: string, repairId: string, userId: string, startedAt: number, endedAt: number | null): void {
  run(
    'INSERT INTO work_logs (id, repair_id, user_id, started_at, ended_at) VALUES (?, ?, ?, ?, ?)',
    [workLogId, repairId, userId, startedAt, endedAt]
  )
}

async function resetData() {
  await db.delete(workLogs)
  // Clean repairs by raw SQL (Drizzle doesn't support delete-all easily on some tables)
  run('DELETE FROM repairs')
  await db.delete(users)
}

// ---------------------------------------------------------------------------
// Tests — computeStaffStats
// ---------------------------------------------------------------------------

describe('computeStaffStats', async () => {
  const { computeStaffStats } = await import('../users.service.js')

  beforeEach(async () => {
    await resetData()
  })

  describe('zero repairs (all zeros/nulls)', () => {
    it('should return zero hours, zero repairs, null avg when user has no data', async () => {
      const userId = await seedUser()

      const stats = await computeStaffStats(userId)

      expect(stats.totalHoursWorked).toBe(0)
      expect(stats.completedRepairs).toBe(0)
      expect(stats.activeRepairs).toBe(0)
      expect(stats.avgRepairDurationMinutes).toBeNull()
    })
  })

  describe('single completed repair with one work log', () => {
    it('should return correct hours and counts for one completed repair', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair(userId, 'completed')

      // Insert a work log: 60 minutes (3600000 ms)
      const startedAt = Date.now() - 3_600_000
      insertWorkLog(crypto.randomUUID(), repairId, userId, startedAt, startedAt + 3_600_000)

      const stats = await computeStaffStats(userId)

      expect(stats.totalHoursWorked).toBe(60) // minutes
      expect(stats.completedRepairs).toBe(1)
      expect(stats.activeRepairs).toBe(0)
      expect(stats.avgRepairDurationMinutes).toBe(60) // 60 / 1 = 60
    })
  })

  describe('multiple repairs with mixed statuses', () => {
    it('should count completed and active correctly, exclude cancelled from both', async () => {
      const userId = await seedUser()

      // 2 completed repairs
      const completed1 = await seedRepair(userId, 'completed')
      const completed2 = await seedRepair(userId, 'completed')

      // 1 in_progress repair (active)
      await seedRepair(userId, 'in_progress')

      // 1 on_hold repair (active — not completed/cancelled)
      await seedRepair(userId, 'on_hold')

      // 1 cancelled repair (should be excluded from both counts)
      await seedRepair(userId, 'cancelled')

      // Work logs: 30 min for completed1, 20 min for completed2 = 50 min total
      const now = Date.now()
      insertWorkLog(crypto.randomUUID(), completed1, userId, now - 1_800_000, now) // 30 min
      insertWorkLog(crypto.randomUUID(), completed2, userId, now - 1_200_000, now) // 20 min

      const stats = await computeStaffStats(userId)

      expect(stats.totalHoursWorked).toBe(50) // minutes
      expect(stats.completedRepairs).toBe(2)
      expect(stats.activeRepairs).toBe(2) // in_progress + on_hold
      expect(stats.avgRepairDurationMinutes).toBe(25) // 50 / 2 = 25
    })

    it('should exclude running timers (null endedAt) from totalHoursWorked', async () => {
      const userId = await seedUser()
      const repairId = await seedRepair(userId, 'in_progress')

      const now = Date.now()
      // Completed work log: 30 min
      insertWorkLog(crypto.randomUUID(), repairId, userId, now - 1_800_000, now)
      // Running timer (null endedAt): should be excluded
      insertWorkLog(crypto.randomUUID(), repairId, userId, now - 600_000, null)

      const stats = await computeStaffStats(userId)

      expect(stats.totalHoursWorked).toBe(30) // only the completed work log
    })

    it('should return null avgRepairDurationMinutes when no completions', async () => {
      const userId = await seedUser()

      // Only active repairs, no completed ones
      await seedRepair(userId, 'in_progress')
      await seedRepair(userId, 'on_hold')

      // Work log exists but repair is not completed
      const repairId = await seedRepair(userId, 'intake')
      const now = Date.now()
      insertWorkLog(crypto.randomUUID(), repairId, userId, now - 1_800_000, now)

      const stats = await computeStaffStats(userId)

      expect(stats.totalHoursWorked).toBe(30) // work log still counted
      expect(stats.completedRepairs).toBe(0)
      expect(stats.activeRepairs).toBe(3)
      expect(stats.avgRepairDurationMinutes).toBeNull() // 0 completions → null
    })
  })

  describe('cancelled repairs excluded from active count', () => {
    it('should not count cancelled repairs as active', async () => {
      const userId = await seedUser()

      await seedRepair(userId, 'cancelled')
      await seedRepair(userId, 'cancelled')
      await seedRepair(userId, 'in_progress') // only this one is active

      const stats = await computeStaffStats(userId)

      expect(stats.completedRepairs).toBe(0)
      expect(stats.activeRepairs).toBe(1) // only in_progress counts
    })
  })
})

